javas.java:

int def defectRatePermil(int:totalDefects, int:sampleSize) {
    if (sampleSize <= 0) {
        return 0;
    }
    return totalDefects * 1000 / sampleSize;
}


boolean def dimensionPass(double:measuredSize, double:targetSize, double:tolerance) {
    if (measuredSize > targetSize + tolerance) {
        return false;
    } else if (measuredSize < targetSize - tolerance) {
        return false;
    } else {
        return true;
    }
}


int def scoreDefects(int:criticalDefects, int:majorDefects, int:minorDefects) {
    int score = 100 - criticalDefects * 40 - majorDefects * 15 - minorDefects * 5;
    if (score < 0) {
        score = 0;
    }
    return score;
}


int def scoreAppearance(int:surfaceScore) {
    if (surfaceScore >= 95) {
        return 0;
    } else if (surfaceScore >= 85) {
        return -10;
    } else {
        return -20;
    }
}


int def scoreDimension(boolean:dimensionPass) {
    if (dimensionPass) {
        return 0;
    } else {
        return -30;
    }
}


int def scoreEquipment(str:equipmentStatus) {
    if (equipmentStatus == "WARNING") {
        return -5;
    } else {
        return 0;
    }
}


str def qualityLevel(int:qualityScore, int:criticalDefects, int:defectRatePermil) {
    if (criticalDefects >= 1 || defectRatePermil >= 200) {
        return "SCRAP";
    } else if (qualityScore < 40 || defectRatePermil >= 100) {
        return "REWORK";
    } else if (qualityScore < 60 || defectRatePermil >= 30) {
        return "HOLD";
    } else {
        return "ACCEPT";
    }
}


str def disposition(str:qualityLevel) {
    if (qualityLevel == "SCRAP") {
        return "SCRAP_BIN";
    } else if (qualityLevel == "REWORK") {
        return "REWORK_LINE";
    } else if (qualityLevel == "HOLD") {
        return "QA_HOLD";
    } else {
        return "NEXT_PROCESS";
    }
}


boolean def needCapa(int:criticalDefects, int:majorDefects, boolean:equipmentWarning) {
    if (criticalDefects >= 1 || majorDefects >= 3 || equipmentWarning) {
        return true;
    } else {
        return false;
    }
}


boolean def releaseAllowed(str:qualityLevel, boolean:dimensionPass) {
    if (qualityLevel == "ACCEPT" && dimensionPass) {
        return true;
    } else {
        return false;
    }
}
